from z3 import *
n=21
E={}
for i in range(n):
 for j in range(i+1,n):
  E[i,j]=Bool(f'e_{i}_{j}')
s=Solver()
# degrees 4..6
for v in range(n):
 inc=[E[min(v,u),max(v,u)] for u in range(n) if u!=v]
 s.add(PbGe([(x,1) for x in inc],4))
 s.add(PbLe([(x,1) for x in inc],6))
# no triangles
for a in range(n):
 for b in range(a+1,n):
  for c in range(b+1,n):
   s.add(Not(And(E[a,b],E[a,c],E[b,c])))
# no 4-cycles: for every 4-set forbid cycles? Equiv any two vertices have at most one common neighbor.
for u in range(n):
 for v in range(u+1,n):
  commons=[]
  for w in range(n):
   if w!=u and w!=v:
    commons.append(And(E[min(u,w),max(u,w)], E[min(v,w),max(v,w)]))
  s.add(PbLe([(c,1) for c in commons],1))
# maybe degree sum parity but no need
print('constraints', len(s.assertions()))
s.set('timeout', 60000)
r=s.check()
print(r)
if r==sat:
 m=s.model()
 edges=[]
 deg=[0]*n
 for (i,j),var in E.items():
  if is_true(m.eval(var, model_completion=True)):
   edges.append((i,j)); deg[i]+=1; deg[j]+=1
 print(len(edges), deg)
 print(edges)

from z3 import *
n=21
E={}
for i in range(n):
 for j in range(i+1,n):
  E[i,j]=Bool('e_%d_%d'%(i,j))
s=Solver()
for v in range(n):
 inc=[E[min(v,u),max(v,u)] for u in range(n) if u!=v]
 s.add(PbGe([(x,1) for x in inc],4))
 s.add(PbLe([(x,1) for x in inc],6))
for a in range(n):
 for b in range(a+1,n):
  for c in range(b+1,n):
   s.add(Or(Not(E[a,b]),Not(E[a,c]),Not(E[b,c])))
for u in range(n):
 for v in range(u+1,n):
  commons=[]
  for w in range(n):
   if w!=u and w!=v:
    commons.append(And(E[min(u,w),max(u,w)], E[min(v,w),max(v,w)]))
  s.add(PbLe([(c,1) for c in commons],1))
print('constraints', len(s.assertions()))
s.set('timeout', 60000)
r=s.check()
print(r)
if r==sat:
 m=s.model()
 edges=[]; deg=[0]*n
 for (i,j),var in E.items():
  val=m[var]
  if val is not None and is_true(val):
   edges.append((i,j)); deg[i]+=1; deg[j]+=1
 print(len(edges), deg)
 print(edges)
